/**
 * What a project calls its gatherer - so every message that says "gather
 * again" can say how.
 *
 * The claim it makes falsifiable: none - this is plumbing. Before it, the
 * bundle header said "Generated by `pnpm evidence`" in every project, and the
 * gate's session-start and block messages said "the project's evidence
 * script" without naming one: an agent told to gather again had to go and find
 * out how, which is the expensive path this package exists to remove.
 *
 * One place to set it, read by the gatherer and the gate alike:
 *
 *     package.json  { "evidenceLayer": { "gather": "pnpm evidence --base origin/main" } }
 *
 * Next, the command a sealed run recorded - what actually gathered the
 * evidence being cited. Then, a project that has an `evidence` script is
 * taken to gather with it, through the package manager its `packageManager`
 * field names, or its lockfile shows (npm when neither says). Anything else answers `null`, and the
 * caller says so in words rather than inventing a command that may not exist.
 *
 * `cliCommandFor` answers the same question for this package's own CLI, so a
 * message that says "run `claims review.md --fix`" can say how, too.
 *
 * Not read: the environment a package manager sets for a script
 * (`npm_lifecycle_event`). A gather called from inside another script - a
 * test suite, a release script - would name that script instead.
 */
import { existsSync, readFileSync } from 'node:fs'
import { join } from 'node:path'
import { isRecord } from './json'

/** The command that gathers evidence in the project at `root`, or `null` when it cannot tell. `recorded` is a sealed run's. */
export function gatherCommandFor(root: string, recorded?: string): string | null {
  const read = readManifest(root)
  const configured = read && isRecord(read.evidenceLayer) ? read.evidenceLayer.gather : undefined
  if (typeof configured === 'string' && configured.trim() !== '') return configured.trim()
  if (typeof recorded === 'string' && recorded.trim() !== '') return recorded.trim()
  if (!read || !isRecord(read.scripts) || typeof read.scripts.evidence !== 'string') return null
  return (packageManagerFor(root) ?? 'npm') + ' run evidence'
}

export type PackageManager = 'npm' | 'pnpm' | 'yarn' | 'bun'

const LOCKFILES: readonly (readonly [string, PackageManager])[] = [
  ['pnpm-lock.yaml', 'pnpm'],
  ['yarn.lock', 'yarn'],
  ['bun.lock', 'bun'],
  ['bun.lockb', 'bun'],
  ['package-lock.json', 'npm'],
]

/**
 * The package manager the project at `root` uses: its `packageManager` field,
 * otherwise the lockfile it has, otherwise `null` - a caller decides what to
 * assume, and says so.
 */
export function packageManagerFor(root: string): PackageManager | null {
  const read = readManifest(root)
  const declared = typeof read?.packageManager === 'string' ? /^(npm|pnpm|yarn|bun)@/.exec(read.packageManager)?.[1] : undefined
  if (declared) return declared as PackageManager
  return LOCKFILES.find(([file]) => existsSync(join(root, file)))?.[1] ?? null
}

/**
 * How to run this package's CLI in the project at `root`, for a message that
 * tells an agent to run one of its commands (`claims review.md --fix`). The
 * package's own checkout runs its last build, as its gate does; any other
 * project runs the copy it installed, through its package manager's runner.
 * A guess at a global install is never made - `npx` finds the local one.
 */
export function cliCommandFor(root: string): string {
  const read = readManifest(root)
  if (read?.name === 'evidence-layer') return 'node dist/bin/evidence-layer.mjs'
  const manager = packageManagerFor(root)
  if (manager === 'pnpm') return 'pnpm exec evidence-layer'
  if (manager === 'yarn') return 'yarn evidence-layer'
  if (manager === 'bun') return 'bunx evidence-layer'
  return 'npx evidence-layer'
}

function readManifest(root: string): Record<string, unknown> | null {
  const path = join(root, 'package.json')
  if (!existsSync(path)) return null
  let manifest: unknown
  try {
    manifest = JSON.parse(readFileSync(path, 'utf8'))
  } catch {
    return null
  }
  return isRecord(manifest) ? manifest : null
}
